26	impl ItemType {
27	    /// The MHPCO price-list row for a main item, or `None` for a component:
28	    /// components are not on the main price list, they are charged per type
29	    /// by `component_charge`.
30	    fn main_item_base_premium(self) -> Option<f64> {
31	        match self {
32	            Self::Sword => Some(100.0),
33	            Self::Amulet => Some(60.0),
34	            Self::Staff => Some(80.0),
35	            Self::Potion => Some(40.0),
36	            Self::Rune | Self::Moonstone => None,
37	        }
38	    }
39	
40	    /// A component -- for example a rune or a moonstone -- is not on the main
41	    /// price list; it is charged per type, as a block of alike components.
42	    fn is_component(self) -> bool {
43	        self.main_item_base_premium().is_none()
44	    }
45	
46	    pub fn parse(name: &str) -> Result<Self, String> {
47	        match name {
48	            "sword" => Ok(Self::Sword),
49	            "amulet" => Ok(Self::Amulet),
50	            "staff" => Ok(Self::Staff),
51	            "potion" => Ok(Self::Potion),
52	            "rune" => Ok(Self::Rune),
53	            "moonstone" => Ok(Self::Moonstone),
54	            unknown => Err(format!("the MHPCO does not insure items of type '{unknown}'")),
55	        }
56	    }
57	}
