65	impl Item {
66	    pub fn new(item_type: ItemType) -> Self {
67	        Self {
68	            item_type,
69	            cursed: false,
70	            enchantment: 0,
71	        }
72	    }
73	
74	    /// The item's enchantment level, as recorded by the MHPCO.
75	    pub fn with_enchantment(mut self, enchantment: u32) -> Self {
76	        self.enchantment = enchantment;
77	        self
78	    }
79	
80	    /// A cursed item carries the MHPCO's risk surcharge.
81	    pub fn cursed(mut self) -> Self {
82	        self.cursed = true;
83	        self
84	    }
85	
86	    /// The item-specific risk surcharges this item carries, charged against the
87	    /// item's own base premium rather than the policy total. A component carries
88	    /// none: the MHPCO records no curse, enchantment or material for one, so it
89	    /// is never an affected item.
90	    fn item_surcharge(&self) -> f64 {
91	        match self.item_type.main_item_base_premium() {
92	            Some(item_base) => item_base * self.risk_surcharge_rate(),
93	            None => 0.0,
94	        }
95	    }
96	
97	    /// Highly enchanted for rating purposes. The MHPCO reads a separate, higher
98	    /// enchantment threshold when reimbursing damage, so this one is named for
99	    /// the premium it surcharges.
100	    fn is_highly_enchanted(&self) -> bool {
101	        self.enchantment >= HIGH_ENCHANTMENT_LEVEL
102	    }
103	
104	    /// Curse and high enchantment are independent risks; an item carrying both
105	    /// is surcharged for both.
106	    fn risk_surcharge_rate(&self) -> f64 {
107	        let curse = if self.cursed { CURSE_SURCHARGE } else { 0.0 };
108	        let enchantment = if self.is_highly_enchanted() {
109	            HIGH_ENCHANTMENT_SURCHARGE
110	        } else {
111	            0.0
112	        };
113	        curse + enchantment
114	    }
115	}
