117	const PROCESSING_FEE: u64 = 5;
118	const FIRST_INSURANCE_SURCHARGE: f64 = 0.10;
119	/// Cursed items add a risk surcharge on their own base premium.
120	const CURSE_SURCHARGE: f64 = 0.50;
121	/// Long-standing customers -- 2 or more years of business with the MHPCO --
122	/// receive a loyalty discount on the policy base premium.
123	const LOYALTY_YEARS: u32 = 2;
124	const LOYALTY_DISCOUNT: f64 = 0.20;
125	/// Customers receive a discount on each contract after their first.
126	const FOLLOW_UP_CONTRACT_DISCOUNT: f64 = 0.15;
127	/// Highly enchanted items -- enchantment level 5 or above -- add a risk
128	/// surcharge on their own base premium.
129	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
130	const HIGH_ENCHANTMENT_SURCHARGE: f64 = 0.30;
131	/// Components -- for example runes and moonstones -- share one price-list row.
132	const COMPONENT_BASE_PREMIUM: f64 = 25.0;
133	
134	/// Premiums are rounded up: the MHPCO's favour is the larger amount.
135	fn round_premium_in_mhpco_favour(amount: f64) -> u64 {
136	    amount.ceil() as u64
137	}
138	
139	/// The policy-wide modifier rate, charged against the policy base premium --
140	/// the sum of all item base premiums. The MHPCO nets its policy-wide modifiers
141	/// against one another: a first insurance carries an initial assessment
142	/// surcharge, a long-standing customer earns a loyalty discount, and every
143	/// contract after the customer's first earns a follow-up discount.
144	fn policy_modifier_rate(customer: &Customer, contract: Contract) -> f64 {
145	    let loyalty = if customer.is_long_standing() {
146	        LOYALTY_DISCOUNT
147	    } else {
148	        0.0
149	    };
150	    let follow_up = match contract {
151	        Contract::First => 0.0,
152	        Contract::FollowUp => FOLLOW_UP_CONTRACT_DISCOUNT,
153	    };
154	    FIRST_INSURANCE_SURCHARGE - loyalty - follow_up
155	}
