157	/// A building block of exactly 3 alike components is offered at this price
158	/// instead of the per-component base premium.
159	const COMPONENT_BLOCK_SIZE: usize = 3;
160	const COMPONENT_BLOCK_BASE_PREMIUM: f64 = 60.0;
161	
162	/// Every item type the MHPCO insures. The price list in
163	/// `main_item_base_premium` decides which of these are components, so that
164	/// list stays the single place recording what a component is.
165	const ALL_ITEM_TYPES: [ItemType; 6] = [
166	    ItemType::Sword,
167	    ItemType::Amulet,
168	    ItemType::Staff,
169	    ItemType::Potion,
170	    ItemType::Rune,
171	    ItemType::Moonstone,
172	];
173	
174	fn component_charge(alike_count: usize) -> f64 {
175	    if alike_count == COMPONENT_BLOCK_SIZE {
176	        COMPONENT_BLOCK_BASE_PREMIUM
177	    } else {
178	        alike_count as f64 * COMPONENT_BASE_PREMIUM
179	    }
180	}
181	
182	/// How many of the policy's items are alike the given component type. Alike
183	/// components are the ones charged together, so this is where the MHPCO's
184	/// reading of "alike" lives.
185	fn alike_component_count(items: &[Item], component_type: ItemType) -> usize {
186	    items
187	        .iter()
188	        .filter(|item| item.item_type == component_type)
189	        .count()
190	}
191	
192	/// Main items are charged one price-list row each, individually.
193	fn main_items_base_premium(items: &[Item]) -> f64 {
194	    items
195	        .iter()
196	        .filter_map(|item| item.item_type.main_item_base_premium())
197	        .sum()
198	}
199	
200	/// Components are charged per group of alike components, so that a group of
201	/// exactly 3 earns the block price.
202	fn component_blocks_base_premium(items: &[Item]) -> f64 {
203	    ALL_ITEM_TYPES
204	        .iter()
205	        .filter(|item_type| item_type.is_component())
206	        .map(|component_type| component_charge(alike_component_count(items, *component_type)))
207	        .sum()
208	}
209	
210	/// The policy base premium is the sum of the items' base premiums, with alike
211	/// components charged as blocks.
212	pub fn policy_base_premium(items: &[Item]) -> f64 {
213	    main_items_base_premium(items) + component_blocks_base_premium(items)
214	}
215	
216	/// Item-specific modifiers apply to the base premium of the affected item, not
217	/// to the policy total.
218	fn item_surcharges(items: &[Item]) -> f64 {
219	    items.iter().map(Item::item_surcharge).sum()
220	}
221	
222	/// A customer's first contract with the MHPCO, or any contract after it.
223	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
224	pub enum Contract {
225	    First,
226	    FollowUp,
227	}
228	
229	/// What the MHPCO rates this policy at, as an exact fraction: the policy base
230	/// premium, modified policy-wide for the customer and the contract, plus the
231	/// surcharges carried by the individual affected items. This is the rating
232	/// decision; it is deliberately unrounded and carries no processing fee.
233	fn rated_premium(customer: &Customer, items: &[Item], contract: Contract) -> f64 {
234	    let policy_base = policy_base_premium(items);
235	    policy_base + policy_base * policy_modifier_rate(customer, contract) + item_surcharges(items)
236	}
237	
238	/// The premium the customer is billed: the MHPCO rates the policy, then settles
239	/// it -- rounding the rated amount in its own favour and adding the processing
240	/// fee at the very end.
241	pub fn quote(customer: &Customer, items: &[Item], contract: Contract) -> u64 {
242	    round_premium_in_mhpco_favour(rated_premium(customer, items, contract)) + PROCESSING_FEE
243	}
